import React from "react";
import { loadFont as loadRokkitt } from "@remotion/google-fonts/Rokkitt";
import { loadFont as loadBitter } from "@remotion/google-fonts/Bitter";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// BAIRRO TATUADO (Rodrigo, Maceió) · promoção 3 flash tattoos por R$100. Vitrine vertical de 28 s sobre a voz do ElevenLabs
// (o locutor, 26,48 s, entra em 0,15 s), com o texto que o cliente mandou. Identidade da arte dele: papel creme, vermelho-tijolo,
// pincelada preta e slab condensada pesada. Foto ou vídeo do cliente em tela cheia; lettering embaixo (cartão creme + pincelada).
// As três fotos que ele pediu entram no "que tal três de uma vez?", uma por batida.
// v3: vídeos trocados pelos originais em alta que o cliente mandou (hq-*.mp4, 1080x1920).
// v2 (retorno): sem o sol no começo, sem o zumbido de abertura, mais motion por cima (círculo desenhado em volta
// de cada tatuagem, ícone desenhado por palavra, estrelas do flash) e transições leves (fusões curtas, sem pincelada cruzando).
// Tempos = tempo da palavra na voz ((arquivo do cliente)).

const { fontFamily: SLAB } = loadRokkitt("normal", { weights: ["800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF } = loadBitter("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });

export const RD_FPS = 30;
const LEAD = 0.15;
export const RD_FRAMES = Math.round(28 * RD_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + LEAD) * RD_FPS));

const PAPER = "#F6F1E6";
const RED = "#A52C11";
const INK = "#1F1F1D";
const SHADOW = "0 14px 40px rgba(0,0,0,0.38)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.bezier(0.34, 1.56, 0.64, 1) });

// trocas de cena (tempo da voz)
const T2 = 2.95, T3 = 5.85, T4 = 11.75, T5 = 17.6, T6 = 21.0;

// ───────── mídia do cliente ─────────
// tamanho de cada foto (para pôr o círculo em cima da tatuagem)
const DIM: Record<string, [number, number]> = { "pedida-1.jpg": [960, 1280], "pedida-2.jpg": [768, 1367], "pedida-3.jpg": [768, 1364], "foto-4.jpg": [799, 1433], "foto-9.jpg": [1080, 1920], "foto-21.jpg": [960, 1280] };
// ring = [centro x, centro y, raio x, raio y] em fração da foto, e o segundo em que o traço começa
type Ring = { c: [number, number, number, number]; at: number; tilt?: number };
const Photo: React.FC<{ src: string; t: number; a: number; b: number; pos?: string; z?: [number, number]; origin?: string; ring?: Ring }> = ({ src, t, a, b, pos = "50% 50%", z = [1.04, 1.14], origin = "50% 50%", ring }) => {
  let ringEl: React.ReactNode = null;
  if (ring && DIM[src]) {
    const [w, h] = DIM[src];
    const s0 = Math.max(1080 / w, 1920 / h);
    const [px, py] = pos.split(" ").map((v) => parseFloat(v) / 100);
    const ox = (1080 - w * s0) * px, oy = (1920 - h * s0) * py;
    const [cx, cy, rx, ry] = ring.c;
    ringEl = <DrawnRing t={t} at={ring.at} x={ox + cx * w * s0} y={oy + cy * h * s0} rx={Math.max(70, rx * w * s0)} ry={Math.max(60, ry * h * s0)} tilt={ring.tilt ?? -8} />;
  }
  return (
    <AbsoluteFill style={{ overflow: "hidden", background: INK }}>
      <AbsoluteFill style={{ transform: `scale(${interpolate(t, [a, b], z, { ...cl, easing: Easing.inOut(Easing.sin) }).toFixed(4)})`, transformOrigin: origin }}>
        <Img src={staticFile(`rodrigo/${src}`)} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos }} />
        {ringEl}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
// círculo feito à mão (1 volta e pouco), creme, que se desenha em volta da tatuagem
const DrawnRing: React.FC<{ t: number; at: number; x: number; y: number; rx: number; ry: number; tilt: number }> = ({ t, at, x, y, rx, ry, tilt }) => {
  const p = k(t, at, 0.55, Easing.bezier(0.45, 0, 0.2, 1));
  if (p <= 0) return null;
  const pts: string[] = [];
  for (let i = 0; i <= 64; i++) {
    const th = -0.5 + (i / 64) * (Math.PI * 2 + 0.75);
    const r = 1.18 + 0.05 * Math.sin(th * 3) + 0.06 * (i / 64);
    pts.push(`${(Math.cos(th) * rx * r).toFixed(1)},${(Math.sin(th) * ry * r).toFixed(1)}`);
  }
  return (
    <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0, overflow: "visible", filter: "drop-shadow(0 3px 6px rgba(0,0,0,0.45))" }}>
      <g transform={`translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${tilt})`}>
        <path d={`M${pts.join(" L")}`} pathLength={1} fill="none" stroke={PAPER} strokeWidth={9} strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 1" strokeDashoffset={1 - p} />
      </g>
    </svg>
  );
};
// estrela de quatro pontas, do flash tradicional: entra girando e fica
const Spark: React.FC<{ t: number; at: number; x: number; y: number; s?: number; c?: string }> = ({ t, at, x, y, s = 60, c = PAPER }) => {
  const e = pop(t, at, 0.5);
  if (e <= 0) return null;
  return (
    <svg width={s} height={s} viewBox="-50 -50 100 100" style={{ position: "absolute", left: x - s / 2, top: y - s / 2, overflow: "visible", transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * 120).toFixed(1)}deg)`, filter: "drop-shadow(0 3px 8px rgba(0,0,0,0.4))" }}>
      <path d="M0 -50 C6 -10 10 -6 50 0 C10 6 6 10 0 50 C-6 10 -10 6 -50 0 C-10 -6 -6 -10 0 -50Z" fill={c} />
    </svg>
  );
};
const Vid: React.FC<{ src: string; t: number; a: number; b: number; from?: number; rate?: number; z?: [number, number]; origin?: string }> = ({ src, t, a, b, from = 0, rate = 1, z = [1.04, 1.14], origin = "50% 45%" }) => (
  <Sequence from={fr(a - 0.3)} layout="none">
    <AbsoluteFill style={{ overflow: "hidden", background: INK }}>
      <OffthreadVideo muted src={staticFile(`rodrigo/${src}`)} trimBefore={Math.round(from * RD_FPS)} playbackRate={rate} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${interpolate(t, [a, b], z, { ...cl, easing: Easing.inOut(Easing.sin) }).toFixed(4)})`, transformOrigin: origin }} />
    </AbsoluteFill>
  </Sequence>
);
// sombra embaixo, só para o lettering descolar da pele
const Shade: React.FC = () => (
  <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 900, background: "linear-gradient(0deg, rgba(20,16,14,0.7) 0%, rgba(20,16,14,0.35) 55%, rgba(20,16,14,0) 100%)" }} />
);

// ───────── lettering: cartão creme (letra vermelha) e pincelada preta (letra creme), como na arte do cliente ─────────
const rnd = (s: number) => { const x = Math.sin(s * 127.1) * 43758.5453; return x - Math.floor(x); };
const brushPath = (seed: number) => {
  const top: string[] = [], bot: string[] = [];
  for (let i = 0; i <= 40; i++) {
    const x = 30 + i * 23.5;
    top.push(`${x.toFixed(1)},${(4 + rnd(seed + i) * 7).toFixed(1)}`);
    bot.push(`${x.toFixed(1)},${(96 - rnd(seed + 50 + i) * 7).toFixed(1)}`);
  }
  // pontas com cerdas
  const right: string[] = [], left: string[] = [];
  for (let j = 0; j <= 8; j++) {
    const y = 8 + j * 10.5;
    right.push(`${(985 - rnd(seed + 90 + j) * 45).toFixed(1)},${y.toFixed(1)}`, `${(1000 - rnd(seed + 110 + j) * 12).toFixed(1)},${(y + 5).toFixed(1)}`);
    left.push(`${(15 + rnd(seed + 130 + j) * 45).toFixed(1)},${(92 - j * 10.5).toFixed(1)}`, `${(rnd(seed + 150 + j) * 12).toFixed(1)},${(87 - j * 10.5).toFixed(1)}`);
  }
  return `M${[...top, ...right, ...bot.reverse(), ...left].join(" L")} Z`;
};
const Brush: React.FC<{ t: number; at: number; color?: string; text: string; size?: number; textColor?: string; seed?: number; d?: number; flat?: boolean }> = ({ t, at, color = INK, text, size = 128, textColor = PAPER, seed = 3, d = 0.38, flat }) => {
  const p = k(t, at, d, Easing.bezier(0.3, 0.7, 0.2, 1));
  const txt = k(t, at + 0.08, 0.4);
  return (
    <div style={{ position: "relative", display: "inline-flex", padding: `${size * 0.14}px ${size * 0.38}px ${size * 0.1}px`, clipPath: `inset(-20% ${((1 - p) * 100).toFixed(2)}% -20% 0)` }}>
      <svg viewBox="0 0 1000 100" preserveAspectRatio="none" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", filter: flat ? undefined : "drop-shadow(0 12px 22px rgba(0,0,0,0.35))" }}>
        <path d={brushPath(seed)} fill={color} />
      </svg>
      <div style={{ position: "relative", fontFamily: SLAB, fontWeight: 900, fontSize: size, lineHeight: 1, letterSpacing: "0.01em", color: textColor, whiteSpace: "nowrap", opacity: txt, transform: `translateX(${((1 - txt) * -30).toFixed(1)}px)` }}>{text}</div>
    </div>
  );
};
const Card: React.FC<{ t: number; at: number; text: string; size?: number; color?: string }> = ({ t, at, text, size = 104, color = RED }) => {
  const e = pop(t, at, 0.45);
  return (
    <div style={{ display: "inline-flex", padding: `${size * 0.16}px ${size * 0.42}px ${size * 0.1}px`, background: PAPER, boxShadow: SHADOW, borderRadius: 6, opacity: Math.min(1, e * 2.5), transform: `translateY(${((1 - e) * 70).toFixed(1)}px) scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>
      <div style={{ fontFamily: SLAB, fontWeight: 900, fontSize: size, lineHeight: 1, color, whiteSpace: "nowrap" }}>{text}</div>
    </div>
  );
};
// bloco de baixo: coluna central, base fixa
const Bottom: React.FC<{ children: React.ReactNode; bottom?: number; gap?: number }> = ({ children, bottom = 300, gap = 4 }) => (
  <div style={{ position: "absolute", left: 120, right: 120, bottom, display: "flex", flexDirection: "column", alignItems: "center", gap }}>{children}</div>
);
// frase que se reveza no mesmo lugar: some inteira antes da próxima
const Swap: React.FC<{ t: number; a: number; b?: number; children: React.ReactNode; h: number }> = ({ t, a, b = 99, children, h }) => {
  if (t < a - 0.05 || t > b + 0.12) return null;
  return <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: h, display: "flex", justifyContent: "center", opacity: 1 - lin(t, b, b + 0.1) }}>{children}</div>;
};

// ───────── ícones simples ─────────
const IcoRuler: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s * 0.5} viewBox="0 0 48 24"><rect x={2} y={4} width={44} height={16} rx={2} fill="none" stroke={c} strokeWidth={3} />{[10, 18, 26, 34].map((x, i) => <line key={x} x1={x} y1={4} x2={x} y2={i % 2 ? 10 : 13} stroke={c} strokeWidth={3} />)}</svg>
);
const IcoDrop: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s * 1.4} height={s} viewBox="0 0 42 30"><path d="M11 2 C11 2 3 13 3 19 a8 8 0 0 0 16 0 C19 13 11 2 11 2Z" fill={INK} /><path d="M31 2 C31 2 23 13 23 19 a8 8 0 0 0 16 0 C39 13 31 2 31 2Z" fill={RED} /></svg>
);
const IcoPin: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s * 1.2} viewBox="0 0 24 29"><path d="M12 1a10.5 10.5 0 0 0-10.5 10.5c0 7.8 10.5 16.5 10.5 16.5s10.5-8.7 10.5-16.5A10.5 10.5 0 0 0 12 1z" fill={c} /><circle cx={12} cy={11.5} r={4} fill={PAPER} /></svg>
);
const IcoInsta: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><rect x={2.5} y={2.5} width={19} height={19} rx={5.5} fill="none" stroke={c} strokeWidth={2.2} /><circle cx={12} cy={12} r={4.4} fill="none" stroke={c} strokeWidth={2.2} /><circle cx={17.4} cy={6.6} r={1.4} fill={c} /></svg>
);
const Chip: React.FC<{ t: number; at: number; children: React.ReactNode; dark?: boolean }> = ({ t, at, children, dark }) => {
  const e = pop(t, at, 0.4);
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 30px", borderRadius: 999, background: dark ? INK : PAPER, boxShadow: SHADOW, fontFamily: SERIF, fontWeight: 700, fontSize: 44, color: dark ? PAPER : INK, whiteSpace: "nowrap", opacity: Math.min(1, e * 2.5), transform: `translateY(${((1 - e) * 40).toFixed(1)}px) scale(${(0.75 + 0.25 * e).toFixed(3)})` }}>{children}</div>
  );
};

// ───────── cena 1 · "Pensou em lançar tattoo nova?" ─────────
const Gancho: React.FC<{ t: number }> = ({ t }) => {
  const punch = interpolate(t, [-0.15, 0.5], [1.32, 1.0], { ...cl, easing: OUT });
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ transform: `scale(${punch.toFixed(4)})` }}>
        <Vid src="hq-20261015_165202.mp4" t={t} a={-0.15} b={T2 + 0.3} from={1.4} z={[1.02, 1.1]} origin="50% 40%" />
      </AbsoluteFill>
      <Shade />
      <Bottom>
        <Card t={t} at={0.05} text="PENSOU EM LANÇAR" size={78} />
        <Brush t={t} at={0.8} text="TATTOO NOVA?" size={98} seed={7} />
      </Bottom>
      <Spark t={t} at={1.05} x={150} y={1420} s={64} />
      <Spark t={t} at={1.2} x={935} y={1590} s={48} c={RED} />
    </AbsoluteFill>
  );
};

// ───────── cena 2 · "Que tal três de uma vez?" (as três fotos que o cliente pediu) ─────────
const TRES: [string, number, string, number][] = [["pedida-1.jpg", T2, "45% 55%", 1], ["pedida-2.jpg", 3.72, "50% 50%", -1], ["pedida-3.jpg", 4.34, "45% 50%", 1]];
const RINGS: [number, number, number, number][] = [[0.53, 0.535, 0.21, 0.13], [0.72, 0.515, 0.165, 0.065], [0.55, 0.485, 0.1, 0.055]];
const Tres: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: INK }}>
    {TRES.map(([src, at, pos, dir], i) => {
      if (t < at - 0.3) return null;
      const next = TRES[i + 1]?.[1] ?? 99;
      if (t > next + 0.35) return null;
      const e = i === 0 ? 1 : k(t, at - 0.24, 0.36, INOUT);
      return (
        <AbsoluteFill key={src} style={{ zIndex: i, opacity: e, transform: `translateX(${((1 - e) * 90 * dir).toFixed(1)}px)` }}>
          <Photo src={src} t={t} a={at - 0.3} b={Math.min(next, T3) + 0.4} pos={pos} z={i === 2 ? [1.26, 1.04] : [1.18, 1.06]} origin={i === 1 ? "72% 50%" : "50% 50%"} ring={{ c: RINGS[i], at: at + 0.12, tilt: [-10, -6, 6][i] }} />
        </AbsoluteFill>
      );
    })}
    <Shade />
    {/* número da peça, no alto, sempre no mesmo lugar */}
    {TRES.map(([, at], i) => {
      const next = TRES[i + 1]?.[1] ?? 99;
      if (t < at - 0.05 || t > next) return null;
      const e = pop(t, at - 0.05, 0.4);
      return (
        <div key={i} style={{ position: "absolute", left: 540 - 95, top: 230, width: 190, height: 190, borderRadius: 95, background: RED, boxShadow: SHADOW, border: `6px solid ${PAPER}`, display: "flex", alignItems: "center", justifyContent: "center", zIndex: 5, transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * -50).toFixed(1)}deg)` }}>
          <div style={{ fontFamily: SLAB, fontWeight: 900, fontSize: 130, lineHeight: 1, color: PAPER, marginTop: 10 }}>{i + 1}</div>
        </div>
      );
    })}
    <div style={{ position: "absolute", inset: 0, zIndex: 6 }}>
      <Bottom>
        <Card t={t} at={3.09} text="QUE TAL" size={88} />
        <Brush t={t} at={4.3} text="3 DE UMA VEZ?" size={92} seed={11} color={RED} />
      </Bottom>
      <Spark t={t} at={4.75} x={140} y={1440} s={66} />
      <Spark t={t} at={4.9} x={945} y={1660} s={50} />
    </div>
  </AbsoluteFill>
);

// ───────── cena 3 · a promoção ─────────
const Promo: React.FC<{ t: number }> = ({ t }) => {
  const stamp = pop(t, 7.12, 0.4);
  return (
    <AbsoluteFill>
      <Vid src="hq-20261015_191337.mp4" t={t} a={T3} b={T4 + 0.3} from={0} z={[1.03, 1.12]} origin="50% 35%" />
      <Shade />
      {/* carimbo "promoção liberada" no alto */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 220, display: "flex", justifyContent: "center" }}>
        <div style={{ padding: "16px 40px 10px", border: `6px solid ${PAPER}`, borderRadius: 10, background: RED, boxShadow: SHADOW, fontFamily: SLAB, fontWeight: 900, fontSize: 56, lineHeight: 1, color: PAPER, letterSpacing: "0.04em", whiteSpace: "nowrap", opacity: Math.min(1, stamp * 3), transform: `scale(${(2.2 - 1.2 * stamp).toFixed(3)}) rotate(${(-4 + (1 - stamp) * -8).toFixed(1)}deg)` }}>PROMOÇÃO LIBERADA</div>
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, bottom: 300, height: 560 }}>
        <Swap t={t} a={6.06} b={8.15} h={560}>
          <div style={{ position: "absolute", bottom: 0 }}><Brush t={t} at={6.06} text="ISSO MESMO!" size={104} seed={19} /></div>
        </Swap>
        <Swap t={t} a={8.3} h={560}>
          <div style={{ position: "absolute", bottom: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
            <Card t={t} at={8.3} text="3 TATTOOS" size={120} />
            <Brush t={t} at={10.1} text="POR R$100" size={116} seed={23} />
            <div style={{ display: "flex", gap: 18, marginTop: 26 }}>
              <Chip t={t} at={10.75}><IcoRuler s={50} c={INK} />Até 5 cm</Chip>
              <Chip t={t} at={11.0}><IcoDrop s={34} />Preta ou vermelha</Chip>
            </div>
          </div>
        </Swap>
      </div>
      <Spark t={t} at={10.3} x={130} y={1380} s={70} />
      <Spark t={t} at={10.45} x={955} y={1240} s={52} c={RED} />
    </AbsoluteFill>
  );
};

// ───────── cena 4 · ideal para… ─────────
const IDEAL: [string, number, string, number][] = [["DELICADA", 12.6, "", 0], ["TRAÇO FINO", 13.62, "", 1], ["SÍMBOLO", 14.66, "", 2], ["PRA COMBINAR", 15.76, "", 3], ["COM ALGUÉM", 16.58, "", 3]];
// delicada: coração · traço fino: linha que ondula · símbolo: estrela · combinar: dois corações
const ICONS = [
  "M50 84 C20 62 10 46 14 32 C18 18 38 14 50 32 C62 14 82 18 86 32 C90 46 80 62 50 84Z",
  "M8 64 C22 30 34 30 42 50 C50 70 62 70 70 46 C76 30 86 28 92 36",
  "M50 8 L61 38 L93 39 L68 58 L77 90 L50 71 L23 90 L32 58 L7 39 L39 38Z",
  "M34 76 C14 60 6 48 9 37 C12 26 27 23 34 36 C41 23 56 26 59 37 C62 48 54 60 34 76Z M66 76 C46 60 38 48 41 37 C44 26 59 23 66 36 C73 23 88 26 91 37 C94 48 86 60 66 76Z",
];
const Ideal: React.FC<{ t: number }> = ({ t }) => {
  const cuts = [T4, 13.55, 14.6, 15.7];
  const media = [
    <Photo key="a" src="foto-4.jpg" t={t} a={T4} b={13.9} pos="50% 30%" z={[1.08, 1.22]} origin="48% 30%" ring={{ c: [0.505, 0.475, 0.12, 0.05], at: 12.75 }} />,
    <Photo key="b" src="foto-9.jpg" t={t} a={13.5} b={14.9} pos="50% 50%" z={[1.3, 1.12]} origin="45% 45%" ring={{ c: [0.46, 0.485, 0.11, 0.075], at: 13.78, tilt: 4 }} />,
    <Photo key="c" src="foto-21.jpg" t={t} a={14.5} b={16.0} pos="40% 50%" z={[1.05, 1.2]} origin="40% 48%" ring={{ c: [0.53, 0.555, 0.19, 0.085], at: 14.82 }} />,
    <Vid key="d" src="hq-20260909_185403.mp4" t={t} a={15.7} b={T5 + 0.3} z={[1.06, 1.16]} origin="55% 40%" />,
  ];
  return (
    <AbsoluteFill style={{ background: INK }}>
      {media.map((m, i) => {
        const a = cuts[i], b = cuts[i + 1] ?? 99;
        if (t < a - 0.3 || t > b + 0.25) return null;
        // cada troca de um jeito: zoom saindo, deslize de cima, giro curto
        const e = i === 0 ? 1 : k(t, a - 0.18, 0.3, INOUT);
        const style: React.CSSProperties = i === 1 ? { opacity: e, transform: `scale(${(1.1 - 0.1 * e).toFixed(4)})` }
          : i === 2 ? { opacity: e, transform: `translateY(${((1 - e) * -80).toFixed(1)}px)` }
          : i === 3 ? { opacity: e, filter: e < 1 ? `blur(${((1 - e) * 12).toFixed(1)}px)` : undefined } : {};
        return <AbsoluteFill key={i} style={{ zIndex: i, ...style }}>{m}</AbsoluteFill>;
      })}
      <div style={{ position: "absolute", inset: 0, zIndex: 9 }}>
        <Shade />
        {IDEAL.slice(0, 4).map(([, at], i) => {
          const next = IDEAL[i + 1]?.[1] ?? 99;
          if (t < at - 0.05 || t > (i === 3 ? 99 : next - 0.1)) return null;
