// ───────── transições leves: cada troca de um jeito, sempre com fusão curta ─────────
type Kind = "rise" | "blur" | "zoom" | "slide" | "paper";
const Trans: React.FC<{ t: number; at: number; kind: Kind; children: React.ReactNode }> = ({ t, at, kind, children }) => {
  const e = interpolate(t, [at - 0.25, at + 0.25], [0, 1], { ...cl, easing: INOUT });
  if (e >= 1) return <AbsoluteFill>{children}</AbsoluteFill>;
  const tr = kind === "rise" ? `translateY(${((1 - e) * 90).toFixed(1)}px)` : kind === "zoom" ? `scale(${(1.1 - 0.1 * e).toFixed(4)})` : kind === "slide" ? `translateX(${((1 - e) * 140).toFixed(1)}px)` : kind === "paper" ? `translateY(${((1 - e) * 50).toFixed(1)}px)` : undefined;
  const blur = kind === "blur" ? 18 : kind === "rise" ? 8 : 0;
  return <AbsoluteFill style={{ opacity: e, transform: tr, filter: blur ? `blur(${((1 - e) * blur).toFixed(1)}px)` : undefined }}>{children}</AbsoluteFill>;
};

