      {show(-1, T2) ? <Gancho t={t} /> : null}
      {show(T2, T3) ? <Trans t={t} at={T2} kind="rise"><Tres t={t} /></Trans> : null}
      {show(T3, T4) ? <Trans t={t} at={T3} kind="blur"><Promo t={t} /></Trans> : null}
      {show(T4, T5) ? <Trans t={t} at={T4} kind="zoom"><Ideal t={t} /></Trans> : null}
      {show(T5, T6) ? <Trans t={t} at={T5} kind="slide"><Vagas t={t} /></Trans> : null}
      {show(T6, 99) ? <Trans t={t} at={T6} kind="paper"><Fecho t={t} /></Trans> : null}
    </AbsoluteFill>
  );
};

